-- 79 tu tiep theo cua Oxford 3000 (entry 101-179, het trang 6 cua 3000.pdf).
-- Nhap vao cung lesson 'Oxford 3000' da tao o 0002; term trung thi cap nhat.

UPDATE lessons SET sub_title = '179 từ vựng thông dụng nhất' WHERE title = 'Oxford 3000';


SELECT (SELECT id FROM lessons WHERE title = 'Oxford 3000'), v.id, v.id
FROM vocab v WHERE v.term IN ('ally','almost','alone','along','alongside','aloud','alphabet','alphabetical','alphabetically','already','also','alter','alternative','alternatively','although','altogether','always','amaze','amazed','amazing','ambition','ambulance','among, amongst','amount','amuse','amused','amusing','analyse, analyze','analysis','ancient','and','anger','angle','angrily','angry','animal','ankle','anniversary','announce','annoy','annoyed','annoying','annual','annually','another','answer','anti','anticipate','anxiety','anxious','anxiously','any','anyone (anybod)','anything','anyway','anywhere','apart','apart from','apart from, aside from','apartment','apologize','apparent','apparently','appeal','appear','appearance','apple','application','apply','appoint','appointment','appreciate','approach','appropriate (to, for)','approval','approve','approving','approximate','approximately')
ON CONFLICT(lesson_id, vocab_id) DO NOTHING;
